/** Flat array of all municipios with their department */
export const ALL_MUNICIPIOS: (Municipio & { department: ColombianDepartment })[] =
  (Object.entries(COLOMBIA_MUNICIPIOS) as [ColombianDepartment, Municipio[]][]).flatMap(
    ([department, municipios]) =>
      municipios.map((m) => ({ ...m, department }))
  );

/** Get municipios for a specific department, sorted alphabetically */
export function getMunicipiosByDepartment(department: string): Municipio[] {
  return COLOMBIA_MUNICIPIOS[department as ColombianDepartment] ?? [];
}
